import{createFinalHandshake,createFinalTeam}from'./native3d/final-scenes.js';
import {geometryScene,mannequinPose,mannequin} from './opportunity-rig.js';
export const finalStages=[['handshake',0,6],['football',6,10],['trophy',10,15],['unbeaten',15,21],['tunnel',21,26],['coach',26,27],['grass',27,31],['studs',31,35],['players',35,39],['boots',39,40],['televisions',40,53],['goalkeeper',53,56],['goal',56,58],['celebration',58,60]].map(([id,from,to])=>({id,from,to}));
export const finalDefaults={finalEnabled:true,finalRate:1,finalLayers:{},finalBindings:{},finalTitle:'4 YEARS\nUNDEFEATED',finalGold:'#efb84b',finalGrain:.06,finalCameraStrength:1,finalHandshakeScene:null,finalTeamScene:null,finalTrophyDelay:1.6,finalFlagDelay:1.35,finalTitleDelay:1.65,finalFireDelay:1.2};
export const finalSources={finalFlag:'final-flag-v95.png',finalStadium:'final-stadium-v94.png',finalHall:'final-hall-v94.png',finalTeam:'final-team-v94.png',finalTrophy:'final-trophy-v94.png'};
export function validateFinal(f){if(!Number.isFinite(f.finalRate)||f.finalRate<.05||f.finalRate>4)throw Error('Rate must be 0.05–4');if(typeof f.finalEnabled!=='boolean'||typeof f.finalTitle!=='string'||!/^#[0-9a-f]{6}$/i.test(f.finalGold))throw Error('Invalid scene settings');for(const k of ['finalLayers','finalBindings'])if(!f[k]||typeof f[k]!=='object'||Array.isArray(f[k]))throw Error('Expected '+k);for(const e of Object.values(f.finalLayers)){if(!e||typeof e!=='object')throw Error('Invalid layer');for(const k of ['x','y','scale','rotation','opacity','blur'])if(e[k]!==undefined&&(!Number.isFinite(e[k])||k==='scale'&&e[k]<=0||k==='opacity'&&(e[k]<0||e[k]>1)||k==='blur'&&e[k]<0))throw Error('Invalid '+k);}return true;}
const handshakeScene=createFinalHandshake(),teamScene=createFinalTeam();
const clamp=x=>Math.max(0,Math.min(1,x));
function text(c,s,x,y,size=36,color='#eee'){c.fillStyle=color;c.font=`800 ${size}px Arial`;c.textAlign='center';c.fillText(s,x,y);}
function layer(c,f,id,draw){const e=f.finalLayers[id]||{};if(e.visible===false)return;c.save();c.translate(e.x||0,e.y||0);c.translate(480,270);c.rotate((e.rotation||0)*Math.PI/180);c.scale(e.scale??1,e.scale??1);c.translate(-480,-270);c.globalAlpha*=e.opacity??1;c.filter=`blur(${e.blur||0}px)`;draw();c.restore();}
function stadium(c,images){const im=images.finalStadium;if(im?.width)c.drawImage(im,0,0,960,540);else{c.fillStyle='#333';c.fillRect(0,170,960,200);for(let n=0;n<600;n++){c.fillStyle=n%2?'#aaa':'#555';c.fillRect((n*47)%960,180+(n*31)%170,3,4);}}}
function boot(c,x,y,s=1){c.save();c.translate(x,y);c.scale(s,s);c.fillStyle='#131416';c.beginPath();c.moveTo(-50,0);c.lineTo(-35,-34);c.quadraticCurveTo(5,-45,32,-14);c.quadraticCurveTo(86,-9,85,7);c.lineTo(-48,10);c.closePath();c.fill();c.strokeStyle='#c4c4bc';c.lineWidth=3;c.stroke();for(let i=0;i<4;i++){c.fillStyle='#999';c.fillRect(-30+i*28,10,8,9);}c.restore();}
function fallback(c,id,a,images){stadium(c,images);c.fillStyle='#0009';c.fillRect(0,0,960,540);if(['football','goal','televisions'].includes(id)){c.strokeStyle='#ddd';c.lineWidth=3;c.strokeRect(650,180,220,150);c.fillStyle='#ddd';c.beginPath();c.arc(150+(a*150)%650,420-Math.abs(Math.sin(a*3))*100,15,0,7);c.fill();}else if(['studs','boots','tunnel'].includes(id)){boot(c,390+Math.sin(a*2)*60,380,2);boot(c,650,410,1.6);}else{for(let i=0;i<3;i++){c.fillStyle=i%2?'#ddd':'#444';c.beginPath();c.ellipse(300+i*160,200,35,45,0,0,7);c.fill();c.fillRect(265+i*160,240,70,170);}}text(c,'ILLUSTRATIVE MOTION · REPLACE WITH LICENSED FOOTAGE',480,510,13,'#ddd');}
export function paintFinal(c,age,images={},input={}){const f={...finalDefaults,...input};const a=Math.max(0,Math.min(59.999,age*f.finalRate)),s=finalStages.find(s=>a>=s.from&&a<s.to),u=a-s.from;c.save();c.scale(c.canvas.width/960,c.canvas.height/540);c.fillStyle='#080a0d';c.fillRect(0,0,960,540);
const media=images[f.finalBindings[s.id]];
if(media&&(media.tagName!=='VIDEO'||media.readyState>=2)){layer(c,f,s.id,()=>c.drawImage(media,0,0,960,540));}
else if(s.id==='handshake'){layer(c,f,'handshake',()=>{if(globalThis.MotionNative3D?.paint){globalThis.MotionNative3D.paint(c,u,f.finalHandshakeScene||handshakeScene);return;}text(c,'Native anatomical engine loading',480,270,24);return;const q=clamp(u/.8),shake=Math.sin(u*9)*.035*(u>1&&u<3?1:0);const cam={eye:[3,1.6,6],target:[0,1.1,0],focal:1000};const scene=geometryScene(cam);for(const [x,color,hat]of[[-.7,'#167cbb',false],[.7,'#e8e4d1',true]]){const p=mannequinPose({x,z:0,yaw:x<0?Math.PI/2:-Math.PI/2});p.rightElbow=[x*.6,1.13,.25];p.rightWrist=[x*(1-q)*.7,1.04+shake,.35];mannequin(scene,p,{color,hat,open:.2});}c.save();if(u>3)c.translate(0,(u-3)*260);scene.paint(c);c.restore();});}
else if(s.id==='trophy'){layer(c,f,'hall',()=>{const g=c.createLinearGradient(0,0,0,540);g.addColorStop(0,'#fbd574');g.addColorStop(.45,'#8c5b07');g.addColorStop(1,'#120b02');c.fillStyle=g;c.fillRect(0,0,960,540);for(let i=0;i<14;i++){c.strokeStyle=i%2?'#ffdf73':'#261604';c.lineWidth=6;c.beginPath();c.moveTo(i*90-200,0);c.lineTo(480,220);c.stroke();}for(let side of[-1,1]){c.strokeStyle='#211607';c.lineWidth=10;c.beginPath();c.moveTo(480+side*60,270);c.lineTo(480+side*550,540);c.stroke();}text(c,'FINAL',480,310,100,f.finalGold);});layer(c,f,'hall-plate',()=>{if(images.finalHall)c.drawImage(images.finalHall,0,0,960,540);text(c,'FINAL',480,330,100,f.finalGold);});layer(c,f,'trophy',()=>{if(u<f.finalTrophyDelay)return;const arrival=clamp((u-f.finalTrophyDelay)/1.1);c.translate(0,(1-arrival)*400);if(images.finalTrophy){const z=1+Math.max(0,u-f.finalTrophyDelay-1)*.30*f.finalCameraStrength;c.translate(480,350);c.scale(z,z);c.drawImage(images.finalTrophy,-80,-210,160,260);return;}const z=1+Math.max(0,u-f.finalTrophyDelay-1)*.30*f.finalCameraStrength;c.translate(480,300);c.scale(z,z);c.fillStyle='#17191c';c.fillRect(-42,50,84,70);const g=c.createLinearGradient(-50,0,50,0);g.addColorStop(0,'#75460d');g.addColorStop(.4,'#fff3ba');g.addColorStop(1,'#b98b24');c.fillStyle=g;c.beginPath();c.moveTo(-45,-100);c.bezierCurveTo(-55,-20,-15,0,-9,20);c.lineTo(-9,50);c.lineTo(9,50);c.lineTo(9,20);c.bezierCurveTo(15,0,55,-20,45,-100);c.closePath();c.fill();});}
else if(s.id==='unbeaten'){layer(c,f,'flag',()=>{if(u<f.finalFlagDelay)return;c.globalAlpha*=clamp((u-f.finalFlagDelay)/.7);if(images.finalFlag){c.drawImage(images.finalFlag,150,60,660,380);return;}for(let i=0;i<3;i++){c.fillStyle=['#a12530','#e8ddcc','#436949'][i];c.fillRect(170,80+i*110,620,110);}});layer(c,f,'team',()=>{if(globalThis.MotionNative3D?.paint){const off=document.createElement('canvas');off.width=960;off.height=540;globalThis.MotionNative3D.paint(off.getContext('2d'),u,f.finalTeamScene||teamScene);c.globalCompositeOperation='source-over';c.drawImage(off,0,0);}});layer(c,f,'fire',()=>{if(u<f.finalFireDelay)return;const fire=images.finalFire;if(fire?.readyState>=2){c.globalCompositeOperation='screen';c.save();c.beginPath();c.rect(0,0,170,540);c.rect(790,0,170,540);c.rect(0,470,960,70);c.clip();c.drawImage(fire,0,0,170,540);c.save();c.translate(960,0);c.scale(-1,1);c.drawImage(fire,0,0,170,540);c.restore();c.restore();return;}return;for(let i=0;i<130;i++){const x=(i*73)%960,y=540-((a*90+i*43)%560);c.fillStyle=`rgba(255,${70+i%130},15,${.25+.5*Math.sin(i)**2})`;c.beginPath();c.ellipse(x<480?x*.26:960-(960-x)*.26,y,12+i%19,25+i%40,Math.sin(a+i),0,7);c.fill();}});layer(c,f,'title',()=>{if(u<f.finalTitleDelay)return;c.translate(0,160*(1-clamp((u-f.finalTitleDelay)/.65)));f.finalTitle.split('\n').forEach((line,i)=>text(c,line,480,405+i*65,64,f.finalGold));});}
else if(s.id==='televisions'){layer(c,f,'studio',()=>{const g=c.createRadialGradient(450,40,10,450,200,650);g.addColorStop(0,'#737373');g.addColorStop(1,'#050505');c.fillStyle=g;c.fillRect(0,0,960,540);});const push=1+u*.018*f.finalCameraStrength;c.save();c.translate(480,300);c.scale(push,push);c.translate(-480,-300);for(const [id,x,y,w,h]of[['tv-left',260,210,240,190],['tv-right',510,250,180,150]])layer(c,f,id,()=>{c.fillStyle='#2b2927';c.fillRect(x-15,y-15,w+50,h+45);c.save();c.beginPath();c.roundRect(x,y,w,h,25);c.clip();c.translate(x,y);c.scale(w/960,h/540);const screen=images[f.finalBindings['tv-screen']];if(screen&&(screen.tagName!=='VIDEO'||screen.readyState>=2))c.drawImage(screen,0,0,960,540);else fallback(c,'televisions',a,images);c.restore();c.strokeStyle='#999';c.lineWidth=2;c.beginPath();c.moveTo(x+w*.5,y-15);c.lineTo(x+w*.2,y-65);c.moveTo(x+w*.5,y-15);c.lineTo(x+w*.8,y-65);c.stroke();c.fillStyle='#38332d';c.fillRect(x-10,y+h+35,w,35);});c.restore();}
else layer(c,f,s.id,()=>fallback(c,s.id,u,images));
if(['handshake','trophy','unbeaten','televisions'].includes(s.id))text(c,'ILLUSTRATIVE RECONSTRUCTION · V95',480,533,10,'#bdbdbd');c.restore();return{source:900+a,id:s.id,local:a};}
